referenceSolutions.javascript:
export function solve(items) {
  const success = items
    .map((x, i) => ({ ...x, i }))
    .filter((x) => x.status === "fulfilled")
    .sort((a, b) => a.delay - b.delay || a.i - b.i)[0];
  if (success) return { status: "fulfilled", value: success.value, time: success.delay };
  return {
    status: "rejected",
    value: items.map((x) => x.value),
    time: Math.max(0, ...items.map((x) => x.delay)),
  };
}

